import Mathlib

/-!
# Quantum EML Activation Functions as Local Coordinates on SU(2)

This file establishes that the **normalized quantum EML activation**

  `qEMLnorm(H, c) = (1/√(1+c)) • (I + i·H)`

for traceless Hermitian 2×2 matrices H with H² = c·I, defines a coordinate chart
on a hemisphere of SU(2). This gives a rigorous foundation for noncommutative
activation functions in quantum machine learning.

## Main results

1. **Obstruction** (`unnormalized_not_unitary`): The raw map `I + i·H` is NOT unitary
   for nonzero traceless Hermitian H. This shows naive scalar EML does not survive
   quantization — normalization is essential.

2. **Key algebraic identity** (`traceless_hermitian_sq_scalar`): Every traceless
   Hermitian 2×2 matrix H satisfies H² = c·I for some c ≥ 0. This is the Pauli
   algebra identity that makes everything work.

3. **Unitarity** (`qEMLnorm_unitary`): The normalized activation lands in the
   unitary group U(2).

4. **Determinant one** (`qEMLnorm_det_one`): The normalized activation has
   determinant 1, hence lands in SU(2).

5. **Surjectivity** (`qEMLnorm_surjective`): Every SU(2) matrix with positive
   trace lies in the image of `qEMLnorm`. This establishes the activation as a
   local coordinate chart on SU(2).

## Cross-domain significance

- **Quantum physics**: The chart parameterizes Bloch sphere rotations via
  Hermitian coordinates.
- **Lie theory**: The normalized map is a variant of the Cayley chart on SU(2).
- **Neural networks**: Provides a Lipschitz-stable activation for quantum gates.
- **Gate synthesis**: Gives an explicit algorithm to decompose single-qubit unitaries.
-/

noncomputable section

open Matrix Complex

/-- Convenient abbreviation for 2×2 complex matrices. -/
abbrev M2 := Matrix (Fin 2) (Fin 2) ℂ

/-! ## Predicates -/

/-- A 2×2 matrix is traceless if its trace vanishes. -/
def IsTraceless (H : M2) : Prop := Matrix.trace H = 0

/-! ## Definitions -/

/-- The normalized quantum EML activation:
  `qEMLnorm(H, c) = (1/√(1+c)) • (I + i·H)`
where c is the scalar such that H² = c·I. -/
def qEMLnorm (H : M2) (c : ℝ) : M2 :=
  ((1 / Real.sqrt (1 + c) : ℝ) : ℂ) • ((1 : M2) + (Complex.I : ℂ) • H)

/-! ## Cayley-Hamilton for 2×2 matrices -/

/-
Cayley-Hamilton for 2×2 matrices: M² = tr(M)·M - det(M)·I.
-/
theorem cayley_hamilton_two (M : M2) :
    M * M = M.trace • M - M.det • (1 : M2) := by
  ext i j ; fin_cases i <;> fin_cases j <;> simp +decide [ Matrix.mul_apply, Matrix.det_fin_two, Matrix.trace_fin_two ] <;> ring!

/-! ## Theorem 1: Obstruction — unnormalized map is not unitary -/

/-
The unnormalized map `I + i·H` is NOT unitary for nonzero traceless Hermitian H.
Witness: H = diag(1,-1) (Pauli Z). Then `(I+iH)(I+iH)† = 2I ≠ I`.
-/
theorem unnormalized_not_unitary :
    ∃ H : M2, H.IsHermitian ∧ IsTraceless H ∧ H ≠ 0 ∧
    ((1 : M2) + (Complex.I : ℂ) • H) * star ((1 : M2) + (Complex.I : ℂ) • H) ≠ 1 := by
  refine' ⟨ Matrix.diagonal <| fun i ↦ if i = 0 then 1 else -1, _, _, _, _ ⟩ <;> norm_num [ IsHermitian, IsTraceless ];
  · exact ne_of_apply_ne ( fun m => m 0 0 ) one_ne_zero;
  · intro h; have := congr_fun ( congr_fun h 0 ) 0; norm_num [ Complex.ext_iff, Matrix.mul_apply ] at this;

/-! ## Theorem 2: Traceless Hermitian 2×2 matrices square to a scalar -/

/-
For a traceless Hermitian 2×2 matrix H, H² is a non-negative real scalar
multiple of the identity. This is the fundamental Pauli algebra identity:
if H = x·σ_x + y·σ_y + z·σ_z, then H² = (x²+y²+z²)·I.
-/
theorem traceless_hermitian_sq_scalar (H : M2)
    (hH : H.IsHermitian) (hT : IsTraceless H) :
    ∃ c : ℝ, 0 ≤ c ∧ H * H = (c : ℂ) • (1 : M2) := by
  have h_diag : H 0 0 + H 1 1 = 0 := by
    convert hT using 1;
    unfold IsTraceless; simp +decide [ Matrix.trace ] ;
  have h_herm : H 0 1 = starRingEnd ℂ (H 1 0) := by
    replace hH := congr_fun ( congr_fun hH 0 ) 1; aesop;
  have h_diag_real : starRingEnd ℂ (H 0 0) = H 0 0 := by
    exact congr_fun ( congr_fun hH 0 ) 00
  have h_diag_real' : starRingEnd ℂ (H 1 1) = H 1 1 := by
    convert congr_arg ( fun x => x 1 1 ) hH using 1;
  refine' ⟨ Complex.re ( H 0 0 * H 0 0 + H 0 1 * starRingEnd ℂ ( H 0 1 ) ), _, _ ⟩;
  · simp_all +decide [ Complex.ext_iff ];
    nlinarith;
  · ext i j ; fin_cases i <;> fin_cases j <;> simp +decide [ *, Matrix.mul_apply, Fin.sum_univ_succ ];
    · simp_all +decide [ Complex.ext_iff ];
      norm_num [ show ( H 0 0 |> Complex.im ) = 0 by linarith ] ; ring;
    · linear_combination' h_diag * starRingEnd ℂ ( H 1 0 );
    · linear_combination' h_diag * H 1 0;
    · simp_all +decide [ Complex.ext_iff, eq_neg_of_add_eq_zero_right h_diag ];
      exact ⟨ by ring, by rw [ show ( H 0 0 |> Complex.im ) = 0 by linarith ] ; ring ⟩

/-! ## Theorem 3: Normalized qEML is unitary -/

/-
If H is traceless Hermitian with H² = c·I (c ≥ 0), then
`qEMLnorm H c` is unitary: it satisfies `A * A† = I`.
-/
theorem qEMLnorm_unitary (H : M2) (c : ℝ)
    (hH : H.IsHermitian) (hT : IsTraceless H)
    (hc : 0 ≤ c)
    (hSq : H * H = (c : ℂ) • (1 : M2)) :
    qEMLnorm H c * star (qEMLnorm H c) = 1 := by
  -- Let's simplify the expression using the fact that multiplication by a scalar commutes with matrix multiplication.
  have h_comm : (1 : M2) + Complex.I • H ≠ 0 := by
    intro h; have := congr_arg Matrix.trace h; norm_num [ hT, hSq, Complex.ext_iff ] at this;
    exact absurd this.1 ( by rw [ hT ] ; norm_num );
  have h_comm : (1 : M2) + Complex.I • H ≠ 0 → ((1 : M2) + Complex.I • H) * star ((1 : M2) + Complex.I • H) = (1 + c) • 1 := by
    simp_all +decide [ Matrix.mul_add, add_mul, mul_add, add_mul, mul_assoc, mul_left_comm, mul_comm ];
    rw [ show star H = H from hH ] ; simp_all +decide [ add_smul, smul_smul ] ;
    abel1;
  simp_all +decide [ qEMLnorm ];
  convert congr_arg ( fun x : M2 => ( ( Real.sqrt ( 1 + c ) ) ⁻¹ : ℂ ) • ( ( Real.sqrt ( 1 + c ) ) ⁻¹ : ℂ ) • x ) h_comm using 1 <;> norm_num [ smul_smul, mul_assoc, mul_left_comm, mul_add, add_mul, mul_comm ];
  · norm_num [ ← mul_assoc, ← smul_assoc ];
  · norm_num [ ← sq, ← smul_assoc, hc ];
    norm_cast ; norm_num [ hc, Real.sq_sqrt ( add_nonneg zero_le_one hc ) ];
    rw [ inv_smul_smul₀ ( by positivity ) ]

/-! ## Theorem 4: Determinant is 1 -/

/-
The normalized qEML map has determinant 1, hence lands in SU(2).
-/
theorem qEMLnorm_det_one (H : M2) (c : ℝ)
    (hH : H.IsHermitian) (hT : IsTraceless H)
    (hSq : H * H = (c : ℂ) • (1 : M2)) :
    (qEMLnorm H c).det = 1 := by
  have := @qEMLnorm_unitary H c hH hT;
  -- Since $qEMLnorm H c$ is unitary, its determinant must be 1.
  have h_det : c ≥ 0 := by
    have := traceless_hermitian_sq_scalar H hH hT;
    obtain ⟨ d, hd₁, hd₂ ⟩ := this; simp_all +decide [ mul_comm ] ;
  have := congr_arg Matrix.det ( this h_det hSq ) ; norm_num at this;
  simp_all +decide [ Matrix.det_fin_two, qEMLnorm ];
  simp_all +decide [ Complex.ext_iff, IsHermitian, IsTraceless ];
  simp_all +decide [ ← Matrix.ext_iff, Fin.forall_fin_two, trace ];
  norm_num [ Complex.ext_iff, Matrix.mul_apply ] at *;
  grind

/-! ## Theorem 5: Surjectivity onto the positive-trace hemisphere of SU(2) -/

/-
Every SU(2) matrix with positive real trace is in the image of `qEMLnorm`.
This establishes qEMLnorm as a local coordinate chart on SU(2), analogous to
the Cayley chart in Lie theory.
-/
set_option maxHeartbeats 800000 in
theorem qEMLnorm_surjective (U : M2)
    (hU : U * star U = 1) (hdet : U.det = 1)
    (htr : 0 < (Matrix.trace U).re) :
    ∃ H : M2, ∃ c : ℝ,
      H.IsHermitian ∧ IsTraceless H ∧ 0 ≤ c ∧
      H * H = (c : ℂ) • (1 : M2) ∧
      qEMLnorm H c = U := by
  -- Set $a := (U.trace.re / 2)$ and $s := 1/a$ (since $U$ has a positive real trace).
  set a := (U.trace.re / 2 : ℝ)
  set s := (1 / a : ℝ);
  -- Set $H := I • (-Complex.I) • (s • U - 1)$ and $c := 4 / t^2 - 1$.
  use (-Complex.I : ℂ) • ((s : ℂ) • U - (1 : M2)), (4 / (U.trace.re)^2 - 1 : ℝ);
  refine' ⟨ _, _, _, _, _ ⟩ <;> norm_num [ IsHermitian, IsTraceless, qEMLnorm ];
  · -- Since $U$ is unitary, we have $Uᴴ = U⁻¹$.
    have hU_inv : Uᴴ = U⁻¹ := by
      rw [ Matrix.inv_eq_right_inv ] ; aesop;
    -- Since $U$ is unitary, we have $U⁻¹ = Uᴴ$.
    have hU_inv_eq : U⁻¹ = (U.trace : ℂ) • 1 - U := by
      rw [ Matrix.inv_def ];
      ext i j ; fin_cases i <;> fin_cases j <;> simp +decide [ *, Matrix.mul_apply, Matrix.adjugate_fin_two ];
      · simp +decide [ trace ];
      · simp +decide [ trace ];
    simp_all +decide [ Complex.ext_iff, Matrix.trace ];
    simp +zetaDelta at *;
    ext i j ; norm_num ; ring;
    fin_cases i <;> fin_cases j <;> norm_num [ Matrix.trace ] <;> ring;
    · norm_num [ Complex.normSq, Complex.ext_iff ] at *;
      field_simp;
      constructor <;> have := congr_fun ( congr_fun hU_inv 0 ) 0 <;> have := congr_fun ( congr_fun hU_inv 1 ) 0 <;> have := congr_fun ( congr_fun hU_inv 0 ) 1 <;> have := congr_fun ( congr_fun hU_inv 1 ) 1 <;> norm_num [ Complex.ext_iff ] at * <;> linarith;
    · simp_all +decide [ Complex.ext_iff, Matrix.inv_def ];
      norm_num [ Complex.normSq ] at *;
      have := congr_fun ( congr_fun hU_inv 0 ) 0; have := congr_fun ( congr_fun hU_inv 1 ) 0; have := congr_fun ( congr_fun hU_inv 0 ) 1; have := congr_fun ( congr_fun hU_inv 1 ) 1; norm_num [ Complex.ext_iff ] at * ; constructor <;> nlinarith [ mul_inv_cancel₀ ( ne_of_gt htr ) ] ;
  · simp +zetaDelta at *;
    rw [ div_mul_eq_mul_div, sub_eq_zero, div_eq_iff ] <;> norm_cast ; ring;
    · have h_trace_real : U 1 1 = star (U 0 0) ∧ U 1 0 = -star (U 0 1) := by
        simp_all +decide [ ← Matrix.ext_iff, Fin.forall_fin_two, Matrix.mul_apply, Matrix.det_fin_two ];
        grind;
      simp_all +decide [ Complex.ext_iff, Matrix.trace ];
    · linarith;
  · -- Since $U$ is unitary with determinant 1, we have $|U 0 0|^2 + |U 0 1|^2 = 1$ and $|U 1 0|^2 + |U 1 1|^2 = 1$.
    have h_unitary : Complex.normSq (U 0 0) + Complex.normSq (U 0 1) = 1 ∧ Complex.normSq (U 1 0) + Complex.normSq (U 1 1) = 1 := by
      simp_all +decide [ ← Matrix.ext_iff, Fin.forall_fin_two, Matrix.mul_apply, Complex.ext_iff ];
      exact ⟨ by simpa [ Complex.normSq_apply, sq ] using hU.1.1.1, by simpa [ Complex.normSq_apply, sq ] using hU.2.2.1 ⟩;
    simp_all +decide [ Complex.ext_iff, Matrix.det_fin_two, Matrix.trace_fin_two ];
    rw [ le_div_iff₀ ] <;> norm_num [ Complex.normSq ] at * <;> nlinarith [ sq_nonneg ( ( U 0 0 |> Complex.re ) - ( U 1 1 |> Complex.re ) ), sq_nonneg ( ( U 0 0 |> Complex.im ) - ( U 1 1 |> Complex.im ) ) ];
  · -- By Cayley-Hamilton, we have $U^2 = \text{tr}(U)U - I$.
    have h_cayley_hamilton : U * U = U.trace • U - (1 : M2) := by
      convert cayley_hamilton_two U using 1;
      aesop;
    simp_all +decide [ mul_sub, sub_mul, smul_sub, sub_smul, mul_smul_comm, smul_smul ];
    rw [ show ( trace U : ℂ ) = ( trace U |> Complex.re ) by
          simp_all +decide [ Complex.ext_iff, Matrix.mul_apply, Matrix.trace_fin_two ];
          have := congr_fun ( congr_fun hU 0 ) 0; have := congr_fun ( congr_fun hU 1 ) 0; have := congr_fun ( congr_fun hU 0 ) 1; have := congr_fun ( congr_fun hU 1 ) 1; simp_all +decide [ Matrix.mul_apply, Complex.ext_iff ] ;
          simp_all +decide [ Matrix.det_fin_two ];
          grind ] ; norm_num [ a, s ] ; ring;
    ext i j ; norm_num ; ring;
    norm_num [ sq, mul_assoc, htr.ne' ];
  · ext i j ; norm_num [ Complex.ext_iff, sq ] ; ring;
    rw [ Real.sqrt_sq ] <;> ring! <;> norm_num [ htr.ne' ];
    linarith

end
